function describe(schema){const paths={};schema.eachPath((name,p)=>{if(name==='_id'||name==='__v')return;const child=p.schema||p.caster?.schema;const element=p.caster&&!child?p.caster:null;let defaultResult=null;if(typeof p.defaultValue==='function'){const before=Date.now(),result=p.defaultValue.call({}),after=Date.now();if(name==='profileID'){assert.match(result,/^[a-f0-9]{24}$/);defaultResult='objectIdHex';}else if(p.instance==='Date'){assert.equal(typeof result,'number');assert(result>=before&&result<=after);defaultResult='dateNow';}else defaultResult=result;}
paths[name]={type:p.instance,required:!!p.isRequired,enum:p.enumValues||[],default:p.defaultValue===undefined?null:typeof p.defaultValue==='function'?'function':p.defaultValue,defaultResult,validators:(p.validators||[]).map(v=>v.type),subdocumentId:child?!!child.options._id:null,children:child?describe(child):null,element:element?{type:element.instance,required:!!element.isRequired,enum:element.enumValues||[],default:element.defaultValue===undefined?null:typeof element.defaultValue==='function'?'function':element.defaultValue,validators:(element.validators||[]).map(v=>v.type)}:null};});return paths;}
