const [mode,dir,...extra]=process.argv.slice(2);assert(['--write','--check'].includes(mode)&&dir&&!extra.length);assert(fs.statSync(dir).isDirectory());const output=path.join(fs.realpathSync(dir),'channel_ai_personality_reference.json');const data=JSON.stringify(artifact,null,2)+'\n';if(mode==='--write')fs.writeFileSync(output,data,{flag:'wx'});else assert.equal(fs.readFileSync(output,'utf8'),data);
